      "content": "import { expect, mock, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

async function fixture() {
  const repository = new InMemoryTaskRepository();
  const task = Task.create('t1', 'Concluir tarefa');
  task.pullEvents();
  await repository.save(task);
  const save = mock(async (aggregate: Task) => repository.save(aggregate));
  const findById = mock(async (id: string) => repository.findById(id));
  const publish = mock(async (_events: readonly DomainEvent[]) => {});
  const ctx: UseCaseContext = { correlationId: 'correlation-1', causationId: 'causation-1', publish };
  const useCase = new CompleteTask({ findById, save });
  return { repository, task, save, findById, publish, ctx, useCase };
}

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'carrega t1, salva completed antes de publicar TaskCompleted e retorna o contrato'), async () => {
  const { repository, task, save, findById, publish, ctx, useCase } = await fixture();
  const operations: string[] = [];
  save.mockImplementation(async (aggregate: Task) => {
    expect(aggregate.status).toBe('completed');
    await repository.save(aggregate);
    operations.push('saved');
  });
  publish.mockImplementation(async (events: readonly DomainEvent[]) => {
    expect(operations).toEqual(['saved']);
    expect((await repository.findById('t1'))?.status).toBe('completed');
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCompleted);
    expect(events[0]!.payload).toEqual({ taskId: 't1' });
    operations.push('published');
  });

  expect(task.status).toBe('pending');
  const output = await useCase.execute({ task_id: 't1' }, ctx);

  expect(output).toEqual({ task_id: 't1', status: 'completed' });
  expect(findById).toHaveBeenCalledTimes(1);
  expect(findById).toHaveBeenCalledWith('t1');
  expect(save).toHaveBeenCalledTimes(1);
  expect(save).toHaveBeenCalledWith(task);
  expect(publish).toHaveBeenCalledTimes(1);
  expect(operations).toEqual(['saved', 'published']);
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'rejeita id inexistente com TASK_NOT_FOUND sem salvar nem publicar'), async () => {
  const { task, save, findById, publish, ctx, useCase } = await fixture();
  const failure = await useCase.execute({ task_id: 'inexistente' }, ctx).catch(error => error);

  expect(failure).toBeInstanceOf(DomainError);
  expect(failure).toHaveProperty('code', 'TASK_NOT_FOUND');
  expect(findById).toHaveBeenCalledWith('inexistente');
  expect(save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(task.status).toBe('pending');
  expect(task.pullEvents()).toEqual([]);
});

test(covers(['usecase:complete_task'], 'rejeita conclusão repetida sem salvar nem publicar novamente'), async () => {
  const { task, save, publish, ctx, useCase } = await fixture();
  await useCase.execute({ task_id: 't1' }, ctx);
  save.mockClear();
  publish.mockClear();

  const failure = await useCase.execute({ task_id: 't1' }, ctx).catch(error => error);

  expect(failure).toBeInstanceOf(DomainError);
  expect(failure).toHaveProperty('code', 'TASK_ALREADY_COMPLETED');
  expect(task.status).toBe('completed');
  expect(save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(task.pullEvents()).toEqual([]);
});

test(covers(['usecase:complete_task'], 'propaga falha de persistência sem publicar os eventos'), async () => {
  const { task, save, publish, ctx, useCase } = await fixture();
  const failure = new Error('Falha ao salvar');
  save.mockImplementation(async () => { throw failure; });

  await expect(useCase.execute({ task_id: 't1' }, ctx)).rejects.toBe(failure);

  expect(save).toHaveBeenCalledTimes(1);
  expect(publish).not.toHaveBeenCalled();
  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCompleted);
});

test(covers(['usecase:complete_task'], 'aguarda publicação e propaga sua falha após salvar'), async () => {
  const { repository, save, publish, ctx, useCase } = await fixture();
  const failure = new Error('Falha ao publicar');
  publish.mockImplementation(async () => { throw failure; });

  await expect(useCase.execute({ task_id: 't1' }, ctx)).rejects.toBe(failure);

  expect(save).toHaveBeenCalledTimes(1);
  expect(publish).toHaveBeenCalledTimes(1);
  expect((await repository.findById('t1'))?.status).toBe('completed');
});
